/**
 * SkyCAD Package Exporter for Circular Connectors
 * Generates authentic native .SkyCadPackage ZIP archives for SkyCAD Electrical's
 * "Import packaged part to catalogue" feature under the Catalogue Tools tab.
 * 
 * Features:
 * - Authentic slash notation in Part number property (e.g. D38999/26WE35PN)
 * - Blank Web and Image properties per project specification
 * - Authentic military contacts (M39029/58-360 for 22D, M39029/58-363 for 20, etc.)
 * - Dynamic pin slicing down to any pin count N <= 128
 * - Verified SkyCadSetting termination block preserving authentic catalogue class schema
 * - Dynamic pin numbering/lettering sequence mapped from layout metadata
 * - Child harness accessories attached (M85049/38-17W)
 * - Native in-browser ZIP generation matching SkyCAD Electrical package schema
 */

(function (window) {
    'use strict';

    const ENV_STRUCTURE_B64 = "";
    const PKG_LIB_B64 = "";
    const PIN_TEMPLATE_B64 = "";
    const ACC_TEMPLATE_B64 = "";
    const CONN_TEMPLATE_B64 = "";
    const SETTING_TEMPLATE_B64 = "";
    const ICON_ADDLABEL_B64 = "";
    const ICON_COMPSMALL_B64 = "";
    const ICON_LABEL_B64 = "";
    const IMG_E35_B64 = "";

    function base64ToUint8(base64) {
        const binaryString = atob(base64);
        const len = binaryString.length;
        const bytes = new Uint8Array(len);
        for (let i = 0; i < len; i++) {
            bytes[i] = binaryString.charCodeAt(i);
        }
        return bytes;
    }

    async function decompressGzip(base64String) {
        const bytes = base64ToUint8(base64String);
        if (typeof DecompressionStream !== 'undefined') {
            try {
                const ds = new DecompressionStream('gzip');
                const writer = ds.writable.getWriter();
                writer.write(bytes);
                writer.close();
                const outputChunks = [];
                const reader = ds.readable.getReader();
                while (true) {
                    const { value, done } = await reader.read();
                    if (done) break;
                    outputChunks.push(value);
                }
                const total = outputChunks.reduce((acc, c) => acc + c.length, 0);
                const res = new Uint8Array(total);
                let off = 0;
                for (const chunk of outputChunks) {
                    res.set(chunk, off);
                    off += chunk.length;
                }
                return res;
            } catch (e) {
                console.warn('DecompressionStream failed, fallback to raw bytes:', e);
            }
        }
        return bytes;
    }

    function findSubarray(src, sub, start) {
        start = start || 0;
        const limit = src.length - sub.length;
        for (let i = start; i <= limit; i++) {
            let match = true;
            for (let j = 0; j < sub.length; j++) {
                if (src[i + j] !== sub[j]) { match = false; break; }
            }
            if (match) return i;
        }
        return -1;
    }

    function rfindSubarray(src, sub, end) {
        const startLimit = (typeof end === 'number' ? end : src.length) - sub.length;
        for (let i = startLimit; i >= 0; i--) {
            let match = true;
            for (let j = 0; j < sub.length; j++) {
                if (src[i + j] !== sub[j]) { match = false; break; }
            }
            if (match) return i;
        }
        return -1;
    }

    function concatUint8(arrays) {
        let total = 0;
        for (let i = 0; i < arrays.length; i++) {
            total += arrays[i].length;
        }
        const out = new Uint8Array(total);
        let offset = 0;
        for (let i = 0; i < arrays.length; i++) {
            out.set(arrays[i], offset);
            offset += arrays[i].length;
        }
        return out;
    }

    function replaceAllSubarray(src, target, replacement) {
        let pos = 0;
        const chunks = [];
        while (true) {
            const idx = findSubarray(src, target, pos);
            if (idx === -1) {
                chunks.push(src.subarray(pos));
                break;
            }
            chunks.push(src.subarray(pos, idx));
            chunks.push(replacement);
            pos = idx + target.length;
        }
        return concatUint8(chunks);
    }

    // CRC32 table for ZIP creation
    const CRC_TABLE = (function () {
        const cTable = new Uint32Array(256);
        for (let n = 0; n < 256; n++) {
            let c = n;
            for (let k = 0; k < 8; k++) {
                c = (c & 1) ? (0xEDB88320 ^ (c >>> 1)) : (c >>> 1);
            }
            cTable[n] = c;
        }
        return cTable;
    })();

    function calculateCRC32(bytes) {
        let crc = 0 ^ (-1);
        for (let i = 0; i < bytes.length; i++) {
            crc = (crc >>> 8) ^ CRC_TABLE[(crc ^ bytes[i]) & 0xFF];
        }
        return (crc ^ (-1)) >>> 0;
    }

    function createZip(files) {
        const localHeaders = [];
        const centralHeaders = [];
        let currentOffset = 0;

        const now = new Date();
        const dosTime = ((now.getHours() << 11) | (now.getMinutes() << 5) | (now.getSeconds() >> 1)) & 0xFFFF;
        const dosDate = (((now.getFullYear() - 1980) << 9) | ((now.getMonth() + 1) << 5) | now.getDate()) & 0xFFFF;

        for (const file of files) {
            const nameBytes = new TextEncoder().encode(file.name);
            const dataBytes = file.data instanceof Uint8Array ? file.data : new TextEncoder().encode(file.data || '');
            const crc = calculateCRC32(dataBytes);
            const size = dataBytes.length;

            // Local file header (30 bytes + name length)
            const localHeader = new Uint8Array(30 + nameBytes.length);
            const lView = new DataView(localHeader.buffer);
            lView.setUint32(0, 0x04034b50, true);  // Local file header signature
            lView.setUint16(4, 20, true);          // Version needed to extract (2.0)
            lView.setUint16(6, 0, true);           // General purpose bit flag
            lView.setUint16(8, 0, true);           // Compression method (0 = store)
            lView.setUint16(10, dosTime, true);    // Last mod file time
            lView.setUint16(12, dosDate, true);    // Last mod file date
            lView.setUint32(14, crc, true);        // CRC-32
            lView.setUint32(18, size, true);       // Compressed size
            lView.setUint32(22, size, true);       // Uncompressed size
            lView.setUint16(26, nameBytes.length, true); // File name length
            lView.setUint16(28, 0, true);          // Extra field length
            localHeader.set(nameBytes, 30);

            localHeaders.push(localHeader);
            localHeaders.push(dataBytes);

            // Central directory file header (46 bytes + name length)
            const centralHeader = new Uint8Array(46 + nameBytes.length);
            const cView = new DataView(centralHeader.buffer);
            cView.setUint32(0, 0x02014b50, true);  // Central dir file header signature
            cView.setUint16(4, 20, true);          // Version made by
            cView.setUint16(6, 20, true);          // Version needed to extract
            cView.setUint16(8, 0, true);           // General purpose bit flag
            cView.setUint16(10, 0, true);          // Compression method
            cView.setUint16(12, dosTime, true);    // Last mod file time
            cView.setUint16(14, dosDate, true);    // Last mod file date
            cView.setUint32(16, crc, true);        // CRC-32
            cView.setUint32(20, size, true);       // Compressed size
            cView.setUint32(24, size, true);       // Uncompressed size
            cView.setUint16(28, nameBytes.length, true); // File name length
            cView.setUint16(30, 0, true);          // Extra field length
            cView.setUint16(32, 0, true);          // File comment length
            cView.setUint16(34, 0, true);          // Disk number start
            cView.setUint16(36, 0, true);          // Internal file attributes
            cView.setUint32(38, 0, true);          // External file attributes
            cView.setUint32(42, currentOffset, true); // Relative offset of local header
            centralHeader.set(nameBytes, 46);

            centralHeaders.push(centralHeader);
            currentOffset += localHeader.length + size;
        }

        const centralDirOffset = currentOffset;
        let centralDirSize = 0;
        for (const ch of centralHeaders) {
            centralDirSize += ch.length;
        }

        // End of central directory record (22 bytes)
        const eocd = new Uint8Array(22);
        const eView = new DataView(eocd.buffer);
        eView.setUint32(0, 0x06054b50, true);      // EOCD signature
        eView.setUint16(4, 0, true);               // Number of this disk
        eView.setUint16(6, 0, true);               // Disk where central dir starts
        eView.setUint16(8, files.length, true);    // Number of central dir records on this disk
        eView.setUint16(10, files.length, true);   // Total number of central dir records
        eView.setUint32(12, centralDirSize, true); // Size of central directory
        eView.setUint32(16, centralDirOffset, true); // Offset of central directory
        eView.setUint16(20, 0, true);              // Comment length

        const allParts = localHeaders.concat(centralHeaders).concat([eocd]);
        return new Blob(allParts, { type: 'application/zip' });
    }

    function encodeLeb128(val) {
        const out = [];
        while (val >= 0x80) {
            out.push((val & 0x7F) | 0x80);
            val >>= 7;
        }
        out.push(val & 0x7F);
        return new Uint8Array(out);
    }

    function decodeLeb128(data, offset) {
        let val = 0, shift = 0, count = 0;
        while (true) {
            const b = data[offset + count];
            val |= (b & 0x7F) << shift;
            count++;
            shift += 7;
            if (!(b & 0x80)) break;
        }
        return { val, count };
    }

    function replaceProperty(data, marker, newValBytes) {
        const idx = findSubarray(data, marker);
        if (idx === -1) return data;
        const { val: oldLen, count: oldLenCount } = decodeLeb128(data, idx + marker.length);
        const lenBytes = encodeLeb128(newValBytes.length);
        return concatUint8([
            data.subarray(0, idx + marker.length),
            lenBytes,
            newValBytes,
            data.subarray(idx + marker.length + oldLenCount + oldLen)
        ]);
    }

    function replacePropertyFrom(data, marker, newValBytes, startOffset) {
        const start = startOffset || 0;
        const idx = findSubarray(data, marker, start);
        if (idx === -1) return { data: data, nextOffset: -1 };
        const { val: oldLen, count: oldLenCount } = decodeLeb128(data, idx + marker.length);
        const lenBytes = encodeLeb128(newValBytes.length);
        const nextOffset = idx + marker.length + lenBytes.length + newValBytes.length;
        const out = concatUint8([
            data.subarray(0, idx + marker.length),
            lenBytes,
            newValBytes,
            data.subarray(idx + marker.length + oldLenCount + oldLen)
        ]);
        return { data: out, nextOffset: nextOffset };
    }


    function base64ToUint8Array(base64) {
        const binStr = atob(base64);
        const len = binStr.length;
        const bytes = new Uint8Array(len);
        for (let i = 0; i < len; i++) {
            bytes[i] = binStr.charCodeAt(i);
        }
        return bytes;
    }

    /**
     * Slices pins and assigns pin labels, 2D layout block, contact references, and properties
     */
    function createAssignedConnectorBytes(baseBytes, pinLabels, partNumber, safePN, contactPN, description, imageFilename, layoutImgBytes, connectorGender) {
        const N = pinLabels.length;
        const oldConnGuidStr = "295662a3-09a7-4c9e-805f-e9f56d2fbf68";
        const newConnGuidStr = (typeof crypto !== 'undefined' && crypto.randomUUID) ? crypto.randomUUID() : 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
            const r = Math.random() * 16 | 0, v = c === 'x' ? r : (r & 0x3 | 0x8);
            return v.toString(16);
        });
        const oldLayoutGuidStr = "1398c085-e152-48ec-84cf-dfe867f27a2c";
        const newLayoutGuidStr = (typeof crypto !== 'undefined' && crypto.randomUUID) ? crypto.randomUUID() : 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
            const r = Math.random() * 16 | 0, v = c === 'x' ? r : (r & 0x3 | 0x8);
            return v.toString(16);
        });

        const encoder = new TextEncoder();
        const oldConnGuid = encoder.encode(oldConnGuidStr);
        const newConnGuid = encoder.encode(newConnGuidStr);
        const oldLayoutGuid = encoder.encode(oldLayoutGuidStr);
        const newLayoutGuid = encoder.encode(newLayoutGuidStr);

        const oldPathStr = "\\Catalogue\\Root Class\\Work field classes\\Component\\Connector\\D38999_26WE35PN-icreated.SkyCadFile";
        const newPathStr = `\\Catalogue\\Root Class\\Work field classes\\Component\\Connector\\${safePN}.SkyCadFile`;
        const oldPath = encoder.encode(oldPathStr);
        const newPath = encoder.encode(newPathStr);

        const oldPnStr = "D38999/26WE35PN-icreated";
        const oldPn = encoder.encode(oldPnStr);
        const newPn = encoder.encode(partNumber);

        // 1. Extract layout body from baseBytes
        const layoutMarker = concatUint8([
            encoder.encode("\x1eSkyCadKernel.SkyCadLayoutBlock%"),
            oldLayoutGuid,
            encoder.encode("/")
        ]);
        const posMarker = findSubarray(baseBytes, layoutMarker);
        if (posMarker === -1) throw new Error("Could not find SkyCadLayoutBlock in template");
        const rawLayoutBody = baseBytes.subarray(posMarker + layoutMarker.length);

        // 2. Modify layout body: Width = 0.50 in (1270), Height = 0.59 in (1502), Option C dynamic image
        const widthGuid = encoder.encode("be54de67-db49-4cd8-b69b-06199034d5b7/");
        const heightGuid = encoder.encode("6601bc12-0d5e-41b2-a8d6-0e62d8a3c17e/");
        const ipXGuid = encoder.encode("ff3cc687-30df-4199-bd3f-3f8f3855c159/");
        const ipYGuid = encoder.encode("4c1e4f05-debc-43b0-aead-3763cf91aa31/");
        const layoutImgMarker = encoder.encode("%3f9852d0-2475-476c-85c4-2dd9277f9183/");

        let modLayoutBody = new Uint8Array(rawLayoutBody);
        // Replace Width \x042540 -> \x041270 (0.50 in = 12.70 mm = 1270 units)
        const wIdx = findSubarray(modLayoutBody, widthGuid);
        if (wIdx !== -1) {
            modLayoutBody.set(encoder.encode("\x041270"), wIdx + widthGuid.length);
        }
        // Replace Height \x043048 -> \x041502 (0.59 in = 15.02 mm = 1502 units, Option C)
        const hIdx = findSubarray(modLayoutBody, heightGuid);
        if (hIdx !== -1) {
            modLayoutBody.set(encoder.encode("\x041502"), hIdx + heightGuid.length);
        }

        // Replace Insertion Point X offset (1270 -> 635) and Y offset (1524 -> 751)
        modLayoutBody = replaceProperty(modLayoutBody, ipXGuid, encoder.encode("635"));
        modLayoutBody = replaceProperty(modLayoutBody, ipYGuid, encoder.encode("751"));

        // Replace Image in LayoutBlock: \{imageFilename} if authentic image exists, else blank (strict no fallback)
        if (imageFilename && layoutImgBytes) {
            const imgBytes = encoder.encode(`\\${imageFilename}`);
            modLayoutBody = replaceProperty(modLayoutBody, layoutImgMarker, imgBytes);

            // Physically scale ImageObject construction points to match 0.5-inch envelope
            const imgObjMarker = encoder.encode("SkyCadKernel.SkyCadImageObject%50bf3cce-aea3-4585-8e28-5839fbd5893f/");
            const imgPos = findSubarray(modLayoutBody, imgObjMarker);
            if (imgPos !== -1) {
                const xMarker = encoder.encode("d3f2a2a2-3307-4efa-b03f-52f8555b36fe/");
                const yMarker = encoder.encode("49996958-aa81-49f7-acd6-f1f56124e9ed/");

                // Point 0 (Top-Left corner: X = -635, Y = -751)
                const r1 = replacePropertyFrom(modLayoutBody, xMarker, encoder.encode("-635"), imgPos);
                modLayoutBody = r1.data;
                const r2 = replacePropertyFrom(modLayoutBody, yMarker, encoder.encode("-751"), r1.nextOffset);
                modLayoutBody = r2.data;

                // Point 1 (Extent / Bottom-Right: X = 1270, Y = 1502)
                const r3 = replacePropertyFrom(modLayoutBody, xMarker, encoder.encode("1270"), r2.nextOffset);
                modLayoutBody = r3.data;
                const r4 = replacePropertyFrom(modLayoutBody, yMarker, encoder.encode("1502"), r3.nextOffset);
                modLayoutBody = r4.data;
            }
        } else {
            modLayoutBody = replaceProperty(modLayoutBody, layoutImgMarker, new Uint8Array(0));
        }


        // Replace GUIDs in LayoutBlock
        modLayoutBody = replaceAllSubarray(modLayoutBody, oldConnGuid, newConnGuid);
        modLayoutBody = replaceAllSubarray(modLayoutBody, oldLayoutGuid, newLayoutGuid);

        let connData;

        if (N === 128) {
            const nextChildIdxBytes = new Uint8Array([
                136 & 0xFF,
                (136 >> 8) & 0xFF,
                (136 >> 16) & 0xFF,
                (136 >> 24) & 0xFF
            ]);
            const layoutHeader = concatUint8([
                newConnGuid,
                encoder.encode("/"),
                nextChildIdxBytes,
                encoder.encode("\x1eSkyCadKernel.SkyCadLayoutBlock%"),
                newLayoutGuid,
                encoder.encode("/")
            ]);
            const posLayoutHeaderStart = posMarker - 4 - 1 - oldConnGuid.length;
            connData = concatUint8([
                baseBytes.subarray(0, posLayoutHeaderStart),
                layoutHeader,
                modLayoutBody
            ]);
            // Pin 128 points to oldLayoutGuid
            connData = replaceAllSubarray(connData, oldLayoutGuid, newLayoutGuid);
        } else {
            // For N < 128:
            // Pin 1 is Child 7. Child 8 is Setting. Pin 2 is Child 9.
            // Pin N is Child 7 + N. Next child index is 8 + N.
            const nextChildIdx = 8 + N;
            const childNextPat = concatUint8([
                encoder.encode("%"),
                oldConnGuid,
                encoder.encode("/"),
                new Uint8Array([
                    nextChildIdx & 0xFF,
                    (nextChildIdx >> 8) & 0xFF,
                    (nextChildIdx >> 16) & 0xFF,
                    (nextChildIdx >> 24) & 0xFF
                ])
            ]);

            const posCNext = findSubarray(baseBytes, childNextPat);
            if (posCNext === -1) throw new Error(`Could not find child index ${nextChildIdx}`);

            // Last pin (Pin N) ends right before posCNext with a 'J' pointer
            const posPinTail = rfindSubarray(baseBytes, new Uint8Array([0x4A]), posCNext); // 'J'
            if (posPinTail === -1) throw new Error(`Could not find pointer tail before child ${nextChildIdx}`);

            // Pin N pointer to LayoutBlock
            const newTail = concatUint8([
                encoder.encode("%"),
                newLayoutGuid,
                encoder.encode("/\x00\x00\x00\x00%")
            ]);

            const nextChildIdxBytes = new Uint8Array([
                nextChildIdx & 0xFF,
                (nextChildIdx >> 8) & 0xFF,
                (nextChildIdx >> 16) & 0xFF,
                (nextChildIdx >> 24) & 0xFF
            ]);

            const layoutHeader = concatUint8([
                newConnGuid,
                encoder.encode("/"),
                nextChildIdxBytes,
                encoder.encode("\x1eSkyCadKernel.SkyCadLayoutBlock%"),
                newLayoutGuid,
                encoder.encode("/")
            ]);

            connData = concatUint8([
                baseBytes.subarray(0, posPinTail),
                newTail,
                layoutHeader,
                modLayoutBody
            ]);
        }

        // Replace path
        const pPath = findSubarray(connData, oldPath);
        if (pPath !== -1) {
            connData = concatUint8([
                connData.subarray(0, pPath - 1),
                new Uint8Array([newPath.length]),
                newPath,
                connData.subarray(pPath + oldPath.length)
            ]);
        }

        // Replace part number
        const pPn = findSubarray(connData, oldPn);
        if (pPn !== -1) {
            connData = concatUint8([
                connData.subarray(0, pPn - 1),
                new Uint8Array([newPn.length]),
                newPn,
                connData.subarray(pPn + oldPn.length)
            ]);
        }

        // Replace connector instance GUID
        connData = replaceAllSubarray(connData, oldConnGuid, newConnGuid);

        // Blank Image, Manufacturer and set dynamic Description
        const imgMarker = encoder.encode("%c99e4224-a653-4d8b-bbe9-1b65b53d7c31/");
        const mfrMarker = encoder.encode("%df4db298-037c-4b35-aa04-6b35dab51f5b/");
        const descMarker = encoder.encode("%4ffe94b7-c9ae-43be-9d3e-1d82323866d8/");

        connData = replaceProperty(connData, imgMarker, new Uint8Array(0));
        connData = replaceProperty(connData, mfrMarker, new Uint8Array(0));
        connData = replaceProperty(connData, descMarker, encoder.encode(description || `${partNumber} Circular Connector`));

        // Morph Web property (Child 4) into Gender property with value "Plug" or "Jack"
        const webMarker = encoder.encode("%2ef8aed9-a150-42e3-bf5d-e0185c7a7f9e/");
        const genderMarker = encoder.encode("%827b9a04-9c5d-4c3d-b892-cb97bad90741/");
        connData = replaceAllSubarray(connData, webMarker, genderMarker);
        connData = replaceProperty(connData, genderMarker, encoder.encode(connectorGender || 'Plug'));

        // Update pin contact references and pin labels
        const defaultContactSafe = encoder.encode("M39029_58-360");
        const marker = encoder.encode("0b1f1e12-ea07-46f9-b6df-55d547649bed/");
        let pos = 0;
        const chunks = [];
        for (let i = 0; i < N; i++) {
            const idx = findSubarray(connData, marker, pos);
            if (idx === -1) throw new Error(`Could not find marker for pin ${i}`);

            let targetSafe = "M39029_58-360";
            if (Array.isArray(contactPN) && contactPN[i]) {
                targetSafe = contactPN[i].safePN || contactPN[i].pn || targetSafe;
            } else if (typeof contactPN === 'string' && contactPN) {
                targetSafe = contactPN.replace(/[/\\\s:]+/g, '_').trim();
            }

            const targetSafeBytes = encoder.encode(targetSafe);

            // Find contact reference in this pin's block (between pos and idx)
            const cIdx = findSubarray(connData, defaultContactSafe, pos);
            if (cIdx !== -1 && cIdx < idx) {
                const preChunk = new Uint8Array(connData.subarray(pos, cIdx));
                if (targetSafeBytes.length !== defaultContactSafe.length) {
                    const lenByteOffset = (cIdx - 25) - pos;
                    if (lenByteOffset >= 0 && lenByteOffset < preChunk.length) {
                        preChunk[lenByteOffset] = 36 + targetSafeBytes.length;
                    }
                }
                chunks.push(preChunk);
                chunks.push(targetSafeBytes);
                chunks.push(connData.subarray(cIdx + defaultContactSafe.length, idx + marker.length));
            } else {
                chunks.push(connData.subarray(pos, idx + marker.length));
            }

            const oldLen = connData[idx + marker.length];
            pos = idx + marker.length + 1 + oldLen;
            const newLbl = encoder.encode(pinLabels[i]);
            chunks.push(new Uint8Array([newLbl.length]));
            chunks.push(newLbl);
        }
        chunks.push(connData.subarray(pos));
        connData = concatUint8(chunks);

        return connData;
    }

    /**
     * Generates a custom contact .SkyCadFile by updating Part Number, safe name, Type (Pin vs Socket), and Description
     */
    function createCustomContactFile(pinTemplateBytes, contactPN, safeContactPN, description) {
        if (!contactPN || contactPN === "M39029/58-360") {
            return pinTemplateBytes;
        }
        const encoder = new TextEncoder();
        let data = new Uint8Array(pinTemplateBytes);

        const oldPnBytes = encoder.encode("M39029/58-360");
        const newPnBytes = encoder.encode(contactPN);
        if (oldPnBytes.length === newPnBytes.length) {
            data = replaceAllSubarray(data, oldPnBytes, newPnBytes);
        }

        const oldSafeBytes = encoder.encode("M39029_58-360");
        const newSafeBytes = encoder.encode(safeContactPN);
        if (oldSafeBytes.length === newSafeBytes.length) {
            data = replaceAllSubarray(data, oldSafeBytes, newSafeBytes);
        }

        // Determine contact gender (Socket vs Pin)
        const isSocket = (contactPN && (contactPN.includes('56-') || contactPN.includes('59-'))) || 
                         (description && description.toLowerCase().includes('socket'));
        
        // Update Type property marker (Pin vs Socket)
        const typeMarker = encoder.encode("%9e962f59-97d8-453e-aad5-5969d6046d2a/");
        data = replaceProperty(data, typeMarker, encoder.encode(isSocket ? "Socket" : "Pin"));

        // Update Description property marker
        let finalDesc = description;
        if (!finalDesc || finalDesc === "Connector Contact") {
            finalDesc = isSocket ? "Socket Contact 22-28 AWG Size 22D Crimp Gold" : "Pin Contact 22-28 AWG Size 22D Crimp Gold";
        } else if (isSocket && contactPN === "M39029/56-348" && !finalDesc.toLowerCase().includes("crimp")) {
            finalDesc = "Socket Contact 22-28 AWG Size 22D Crimp Gold";
        }
        const descMarker = encoder.encode("%4ffe94b7-c9ae-43be-9d3e-1d82323866d8/");
        data = replaceProperty(data, descMarker, encoder.encode(finalDesc));

        return data;
    }

    const MIL_STD_CONTACTS = {
        '22D': {
            P: { pn: "M39029/58-360", desc: "Size 22D Pin Contact", safePN: "M39029_58-360", size: "22D" },
            S: { pn: "M39029/56-348", desc: "Size 22D Socket Contact", safePN: "M39029_56-348", size: "22D" }
        },
        '20': {
            P: { pn: "M39029/58-363", desc: "Size 20 Pin Contact", safePN: "M39029_58-363", size: "20" },
            S: { pn: "M39029/56-351", desc: "Size 20 Socket Contact", safePN: "M39029_56-351", size: "20" }
        },
        '16': {
            P: { pn: "M39029/58-364", desc: "Size 16 Pin Contact", safePN: "M39029_58-364", size: "16" },
            S: { pn: "M39029/56-352", desc: "Size 16 Socket Contact", safePN: "M39029_56-352", size: "16" }
        },
        '12': {
            P: { pn: "M39029/58-365", desc: "Size 12 Pin Contact", safePN: "M39029_58-365", size: "12" },
            S: { pn: "M39029/56-353", desc: "Size 12 Socket Contact", safePN: "M39029_56-353", size: "12" }
        },
        '10': {
            P: { pn: "M39029/58-528", desc: "Size 10 Pin Power Contact", safePN: "M39029_58-528", size: "10" },
            S: { pn: "M39029/56-527", desc: "Size 10 Socket Power Contact", safePN: "M39029_56-527", size: "10" }
        },
        '8': {
            P: { pn: "M39029/60-367", desc: "Size 8 Pin Power Contact", safePN: "M39029_60-367", size: "8" },
            S: { pn: "M39029/59-366", desc: "Size 8 Socket Power Contact", safePN: "M39029_59-366", size: "8" }
        }
    };

    const AS_STD_CONTACTS = {
        '24': {
            P: { pn: "605719-31", desc: "Size 24 Pin Contact (Deutsch AutoSport)", safePN: "605719-31", size: "24" },
            S: { pn: "605721", desc: "Size 24 Socket Contact (Deutsch AutoSport)", safePN: "605721", size: "24" }
        },
        '23': {
            P: { pn: "604927-31", desc: "Size 23 Pin Contact (Deutsch AutoSport)", safePN: "604927-31", size: "23" },
            S: { pn: "604935", desc: "Size 23 Socket Contact (Deutsch AutoSport)", safePN: "604935", size: "23" }
        },
        '22': {
            P: { pn: "38941-22", desc: "Size 22 Pin Contact (Deutsch AutoSport)", safePN: "38941-22", size: "22" },
            S: { pn: "38943-22", desc: "Size 22 Socket Contact (Deutsch AutoSport)", safePN: "38943-22", size: "22" }
        },
        '20': {
            P: { pn: "38941-20", desc: "Size 20 Pin Contact (Deutsch AutoSport)", safePN: "38941-20", size: "20" },
            S: { pn: "38943-20", desc: "Size 20 Socket Contact (Deutsch AutoSport)", safePN: "38943-20", size: "20" }
        },
        '16': {
            P: { pn: "38941-16", desc: "Size 16 Pin Contact (Deutsch AutoSport)", safePN: "38941-16", size: "16" },
            S: { pn: "38943-16", desc: "Size 16 Socket Contact (Deutsch AutoSport)", safePN: "38943-16", size: "16" }
        }
    };

    /**
     * Maps each pin label to its exact contact size and authentic part number.
     * Supports layouts with contactMap (e.g. J-4 / 25-4) as well as multi-size counts partitions.
     */
    function resolvePinContactAssignments(pins, layout, gender, isAutoSport, customContacts) {
        const db = isAutoSport ? AS_STD_CONTACTS : MIL_STD_CONTACTS;
        const defaultSize = isAutoSport ? '22' : '22D';
        const contactMap = (layout && layout.contactMap) || null;
        const counts = (layout && layout.counts) || {};

        // Find fallback/remaining size if contactMap exists
        let nonMappedSize = defaultSize;
        if (counts && Object.keys(counts).length > 0) {
            const mappedSizes = contactMap ? Object.keys(contactMap) : [];
            const remaining = Object.keys(counts).filter(sz => !mappedSizes.includes(sz));
            nonMappedSize = remaining.length > 0 ? remaining[0] : Object.keys(counts)[0];
        }

        // Pre-build sequential size partition if counts has multiple sizes and no contactMap
        const seqSizes = [];
        if (!contactMap && counts && Object.keys(counts).length > 1) {
            for (const [sz, qty] of Object.entries(counts)) {
                for (let k = 0; k < qty; k++) seqSizes.push(sz);
            }
        }

        // Map custom contacts by size if provided
        const customBySize = {};
        if (customContacts && Array.isArray(customContacts)) {
            customContacts.forEach(c => {
                if (c.size) customBySize[c.size] = c;
            });
        }

        const assignments = [];
        const uniqueContacts = {};

        for (let i = 0; i < pins.length; i++) {
            const p = pins[i];
            let sz = null;

            if (contactMap) {
                for (const [mapSize, pinList] of Object.entries(contactMap)) {
                    if (Array.isArray(pinList) && pinList.includes(p)) {
                        sz = mapSize;
                        break;
                    }
                }
                if (!sz) sz = nonMappedSize;
            } else if (seqSizes.length > i) {
                sz = seqSizes[i];
            } else if (counts && Object.keys(counts).length > 0) {
                sz = Object.keys(counts)[0];
            } else {
                sz = defaultSize;
            }

            // Resolve contact PN, description, and safe filename for this size
            let resolvedContact = null;
            if (customBySize[sz]) {
                const cc = customBySize[sz];
                resolvedContact = {
                    pn: cc.pn,
                    desc: cc.desc || `Size ${sz} ${gender === 'S' ? 'Socket' : 'Pin'} Contact`,
                    safePN: (cc.pn || '').replace(/[/\\\s:]+/g, '_').trim(),
                    size: sz
                };
            } else if (db[sz] && db[sz][gender]) {
                resolvedContact = { ...db[sz][gender], size: sz };
            } else if (db[defaultSize] && db[defaultSize][gender]) {
                resolvedContact = { ...db[defaultSize][gender], size: defaultSize };
            } else {
                resolvedContact = {
                    pn: gender === 'S' ? "M39029/56-348" : "M39029/58-360",
                    desc: `Size ${sz} ${gender === 'S' ? 'Socket' : 'Pin'} Contact`,
                    safePN: gender === 'S' ? "M39029_56-348" : "M39029_58-360",
                    size: sz
                };
            }

            assignments.push({
                index: i,
                pin: p,
                size: sz,
                pn: resolvedContact.pn,
                desc: resolvedContact.desc,
                safePN: resolvedContact.safePN
            });

            if (!uniqueContacts[resolvedContact.pn]) {
                uniqueContacts[resolvedContact.pn] = {
                    pn: resolvedContact.pn,
                    desc: resolvedContact.desc,
                    safePN: resolvedContact.safePN,
                    size: sz,
                    count: 1
                };
            } else {
                uniqueContacts[resolvedContact.pn].count++;
            }
        }

        const dominantContact = assignments.length > 0 ? assignments[0] : {
            pn: gender === 'S' ? "M39029/56-348" : "M39029/58-360",
            desc: "Size 22D Pin Contact",
            safePN: gender === 'S' ? "M39029_56-348" : "M39029_58-360",
            size: defaultSize
        };

        return {
            assignments,
            uniqueContacts,
            dominantContact
        };
    }

    const SkyCadExporter = {
        /**
         * Cleans a part number into a safe filename string
         */
        toSafePN: function(pn) {
            if (!pn) return 'CONNECTOR';
            return pn.replace(/[/\\\s:]+/g, '_').trim();
        },

        /**
         * Resolves the manufacturer name based on connector series
         */
        getManufacturer: function(seriesId) {
            if (seriesId === 'deutsch_autosport' || seriesId === 'ashd' || seriesId === 'asl') {
                return 'TE Connectivity / DEUTSCH';
            }
            return 'Amphenol Aerospace';
        },

        /**
         * Assembles a comprehensive connector data model from a calculated solution
         */
        formatConnectorData: function(connObj, pair, isPrimary) {
            if (!connObj) return null;

            const isAutoSport = (pair && pair.pnType === 'as') || connObj.seriesId === 'deutsch_autosport' || connObj.seriesId === 'ashd';
            const seriesTitle = isAutoSport ? 'Deutsch AutoSport' : ((pair && pair.pnType === 'comm') ? 'Commercial Tri-Start' : 'MIL-DTL-38999 Series III');
            const mfr = this.getManufacturer(connObj.seriesId);

            const activePN = connObj.activePN || connObj.milPN || connObj.commPN || connObj.asPN;
            const safePN = this.toSafePN(activePN);

            // Extract layout pins if available
            const layout = connObj.layoutObj || 
                ((typeof DataService !== 'undefined' && DataService.getLayoutByArrangement) ? DataService.getLayoutByArrangement(connObj.arrangement) : 
                ((typeof masterLayouts !== 'undefined') ? masterLayouts.find(l => l.arrangement === connObj.arrangement) : null));
            
            let pins = (layout && layout.pins && layout.pins.length > 0) ? layout.pins.slice() : [];
            const pinCount = (layout && (layout.totalPins || pins.length)) || (connObj.contacts ? connObj.contacts.reduce((sum, c) => sum + (c.qty || 0), 0) : 55);

            if (pins.length === 0) {
                for (let i = 1; i <= pinCount; i++) {
                    pins.push(String(i));
                }
            }

            // Layout Insert Image filename resolution (Strict no fallback)
            let imageFilename = null;
            if (layout && layout.diagramImg) {
                imageFilename = layout.diagramImg.split('/').pop();
            } else if (connObj.arrangement) {
                imageFilename = (typeof getInsertImageFilename === 'function') 
                    ? getInsertImageFilename(connObj.arrangement, connObj.shellSize)
                    : `${connObj.arrangement}.png`;
            }

            // Connector Gender (Plug vs Jack) for SkyCAD Catalogue Class
            const stLower = (connObj.shellType || '').toLowerCase();
            const pnUpper = (activePN || '').toUpperCase();
            const isPlug = stLower.includes('plug') || pnUpper.includes('/26') || pnUpper.includes('AS6') || pnUpper.includes('TV06') || pnUpper.includes('TVS06');
            const connectorGender = isPlug ? 'Plug' : 'Jack';

            // Contact Part Number & Gender resolution (with authentic per-pin mixed contact support)
            const gender = connObj.contactType || (activePN && activePN.includes('S') ? 'S' : 'P');
            const customContactsList = connObj.resolvedContacts || connObj.contacts;
            const contactResolution = resolvePinContactAssignments(pins, layout, gender, isAutoSport, customContactsList);

            const dominantContact = contactResolution.dominantContact;
            const contactPN = dominantContact.pn;
            const contactDesc = dominantContact.desc;

            // Child Accessories:
            const accessories = [];

            // Backshell / Strain relief
            if (connObj.shellType !== 'Box Mount' && connObj.selectedBackshell && connObj.selectedBackshell !== 'NONE') {
                const bsOpts = (typeof getBackshellOptions === 'function') ? getBackshellOptions(connObj.shellSize, connObj.finish) : null;
                const bs = bsOpts ? bsOpts[connObj.selectedBackshell] : null;
                if (bs) {
                    accessories.push({
                        type: 'Backshell',
                        pn: bs.pn,
                        desc: bs.desc,
                        manufacturer: isAutoSport ? 'TE Connectivity / Raychem' : 'Amphenol Aerospace',
                        qty: 1
                    });
                }
            }

            // Protective Dust Cap
            if (connObj.includeDustCap) {
                const capOpts = (typeof getDustCapOptions === 'function') ? getDustCapOptions(connObj.shellSize, connObj.finish, connObj.letterCode) : null;
                const cap = capOpts ? (connObj.shellType === 'Plug' ? capOpts.plugCap : capOpts.receptacleCap) : null;
                if (cap) {
                    accessories.push({
                        type: 'Dust Cap',
                        pn: cap.pn,
                        desc: cap.desc,
                        manufacturer: mfr,
                        qty: 1
                    });
                }
            }

            // Flange Accessory / Nut plate
            if (connObj.flangeAcc && connObj.flangeAcc !== 'N/A (Integral Flange)') {
                accessories.push({
                    type: 'Flange Accessory',
                    pn: connObj.flangeAcc.split(' ')[0],
                    desc: 'M85049/95 Flange Nut Plate',
                    manufacturer: 'Mil-Spec / Glenair',
                    qty: 1
                });
            }

            // Contacts BOM
            if (contactResolution.uniqueContacts && Object.keys(contactResolution.uniqueContacts).length > 0) {
                Object.values(contactResolution.uniqueContacts).forEach(c => {
                    accessories.push({
                        type: 'Contact',
                        pn: c.pn,
                        desc: c.desc,
                        manufacturer: isAutoSport ? 'TE Connectivity / DEUTSCH' : 'Mil-Spec (M39029)',
                        qty: c.count
                    });
                });
            } else if (connObj.contacts && connObj.contacts.length > 0) {
                connObj.contacts.forEach(c => {
                    accessories.push({
                        type: 'Contact',
                        pn: c.pn,
                        desc: c.desc,
                        manufacturer: isAutoSport ? 'TE Connectivity / DEUTSCH' : 'Mil-Spec (M39029)',
                        qty: c.qty || pinCount
                    });
                });
            }

            const genderWord = gender === 'S' ? 'Socket' : 'Pin';
            const contactMixSummary = Object.values(contactResolution.uniqueContacts)
                .map(c => `${c.count}x #${c.size}`)
                .join(', ');
            let detailedDesc = `${seriesTitle} ${connObj.shellType || 'Connector'}, Shell ${connObj.shellSize || ''} (${connObj.arrangement || ''}), ${pinCount} ${genderWord} Contacts (${contactMixSummary})`;

            return {
                partNumber: activePN,
                safePN: safePN,
                description: detailedDesc,
                manufacturer: mfr,
                series: connObj.seriesId || 'd38999',
                shellSize: connObj.shellSize,
                shellType: connObj.shellType,
                connectorGender: connectorGender,
                arrangement: connObj.arrangement,
                imageFilename: imageFilename,
                diagramImg: layout ? layout.diagramImg : null,
                pinCount: pinCount,
                pins: pins,
                pinAssignments: contactResolution.assignments,
                uniqueContacts: Object.values(contactResolution.uniqueContacts),
                contactPN: contactPN,
                contactDesc: contactDesc,
                contactMap: layout ? layout.contactMap : null,
                accessories: accessories
            };
        },

        /**
         * Generates the .SkyCadPackage Blob for a connector
         */
        generatePackageBlob: async function(connectorData) {
            const safePN = connectorData.safePN || this.toSafePN(connectorData.partNumber);
            const pkgFolder = `${safePN} Package`;

            // 1. Inflate base templates
            const [
                envStructureBytes,
                pkgLibBytes,
                pinTemplateBytes,
                accTemplateBytes,
                connTemplateBytes,
                iconAddlabelBytes,
                iconCompsmallBytes,
                iconLabelBytes,
                imgE35Bytes
            ] = await Promise.all([
                decompressGzip(ENV_STRUCTURE_B64),
                decompressGzip(PKG_LIB_B64),
                decompressGzip(PIN_TEMPLATE_B64),
                decompressGzip(ACC_TEMPLATE_B64),
                decompressGzip(CONN_TEMPLATE_B64),
                decompressGzip(ICON_ADDLABEL_B64),
                decompressGzip(ICON_COMPSMALL_B64),
                decompressGzip(ICON_LABEL_B64),
                decompressGzip(IMG_E35_B64)
            ]);

            const contactPN = connectorData.contactPN || "M39029/58-360";
            const safeContactPN = this.toSafePN(contactPN);
            const rawImgFilename = connectorData.imageFilename || null;
            const connectorGender = connectorData.connectorGender || 'Plug';

            // 2. Resolve layout diagram image bytes (Strict no fallback)
            let layoutImgBytes = null;
            let imgFilename = null;

            if (rawImgFilename) {
                // Check pre-bundled window.insertImageBase64 first (100% reliable on file:// protocol)
                if (typeof window !== 'undefined' && window.insertImageBase64) {
                    const b64 = window.insertImageBase64[rawImgFilename] ||
                                window.insertImageBase64[rawImgFilename.toLowerCase()] ||
                                window.insertImageBase64[rawImgFilename.toUpperCase()];
                    if (b64) {
                        layoutImgBytes = base64ToUint8Array(b64);
                        imgFilename = rawImgFilename;
                    }
                }

                // Fallback to fetch if not pre-bundled
                if (!layoutImgBytes && typeof fetch === 'function') {
                    const imgCandidates = [];
                    if (connectorData.diagramImg) imgCandidates.push(connectorData.diagramImg);
                    imgCandidates.push(`assets/inserts/${rawImgFilename}`);
                    imgCandidates.push(`assets/inserts/${rawImgFilename.toLowerCase()}`);
                    for (const url of imgCandidates) {
                        try {
                            const resp = await fetch(url);
                            if (resp.ok) {
                                const buf = await resp.arrayBuffer();
                                layoutImgBytes = new Uint8Array(buf);
                                imgFilename = rawImgFilename;
                                break;
                            }
                        } catch (e) {
                            // Ignore fetch/CORS errors
                        }
                    }
                }
            }

            // 3. Serialize connector with dynamic pin slicing, assigned labels, 2D layout block, blank properties, dynamic gender, per-pin contacts
            const customSkyCadFile = createAssignedConnectorBytes(
                connTemplateBytes,
                connectorData.pins || [],
                connectorData.partNumber,
                safePN,
                connectorData.pinAssignments || connectorData.contactPN,
                connectorData.description,
                imgFilename,
                layoutImgBytes,
                connectorGender
            );

            // 4. Serialize contact files for all unique contacts
            const contactFiles = [];
            const uniqueContacts = (connectorData.uniqueContacts && connectorData.uniqueContacts.length > 0)
                ? connectorData.uniqueContacts
                : [{
                    pn: contactPN,
                    safePN: safeContactPN,
                    desc: connectorData.contactDesc || "Connector Contact"
                }];

            uniqueContacts.forEach(uc => {
                const cFile = createCustomContactFile(
                    pinTemplateBytes,
                    uc.pn,
                    uc.safePN,
                    uc.desc || "Connector Contact"
                );
                contactFiles.push({
                    name: `${pkgFolder}/Catalogue/Connector pin/${uc.safePN}.SkyCadFile`,
                    data: cFile
                });
            });

            // 5. PackageInfo.txt
            const packageInfoText = `\\Catalogue\\Root Class\\Work field classes\\Component\\Connector\\${safePN}.SkyCadFile\r\n1.3.65.17278\r\n`;

            // 6. Detailed child accessories BOM CSV
            let accCsv = "Parent Connector,Accessory Type,Part Number,Description,Manufacturer,Quantity\r\n";
            if (connectorData.accessories && connectorData.accessories.length > 0) {
                connectorData.accessories.forEach(a => {
                    accCsv += `"${connectorData.partNumber}","${a.type}","${a.pn}","${a.desc}","${a.manufacturer}",${a.qty}\r\n`;
                });
            } else {
                accCsv += `"${connectorData.partNumber}","None","N/A","No optional accessories configured","N/A",0\r\n`;
            }

            // 7. Pin definition schedule
            let pinSummary = `Connector: ${connectorData.partNumber}\r\n`;
            pinSummary += `Arrangement: ${connectorData.arrangement || 'N/A'}\r\n`;
            pinSummary += `Total Contacts: ${connectorData.pinCount || (connectorData.pins ? connectorData.pins.length : 'N/A')}\r\n\r\n`;
            pinSummary += `Pin Schedule:\r\n`;
            if (connectorData.pins && connectorData.pins.length > 0) {
                connectorData.pins.forEach((p, idx) => {
                    const assign = (connectorData.pinAssignments && connectorData.pinAssignments[idx])
                        ? connectorData.pinAssignments[idx]
                        : null;
                    const assignedPN = assign ? assign.pn : contactPN;
                    const assignedSize = assign ? ` (Size #${assign.size})` : '';
                    pinSummary += `  Pin ${idx + 1}: ${p}${assignedSize} (Assigned ${assignedPN})\r\n`;
                });
            }

            // 8. Update Package library.SkyCadFile to reference new package folder name
            const oldPkgFolderBytes = new TextEncoder().encode("D38999_26WE35PN-icreated Package");
            const newPkgFolderBytes = new TextEncoder().encode(pkgFolder);
            let customPkgLib = pkgLibBytes;
            if (oldPkgFolderBytes.length === newPkgFolderBytes.length) {
                customPkgLib = replaceAllSubarray(pkgLibBytes, oldPkgFolderBytes, newPkgFolderBytes);
            }

            // 9. Assemble files for ZIP archive matching authentic schema
            const files = [
                {
                    name: `${pkgFolder}/PackageInfo.txt`,
                    data: packageInfoText
                },
                {
                    name: `${pkgFolder}/EnvironmentStructure.SkyCadFile`,
                    data: envStructureBytes
                },
                {
                    name: `${pkgFolder}/Catalogue/Library/Package library.SkyCadFile`,
                    data: customPkgLib
                },
                ...contactFiles,
                {
                    name: `${pkgFolder}/Catalogue/Harness accessory/M85049_38-17W.SkyCadFile`,
                    data: accTemplateBytes
                },
                {
                    name: `${pkgFolder}/Catalogue/Root Class/Work field classes/Component/Connector/${safePN}.SkyCadFile`,
                    data: customSkyCadFile
                },
                {
                    name: `${pkgFolder}/Icons/addlabelicon.png`,
                    data: iconAddlabelBytes
                },
                {
                    name: `${pkgFolder}/Icons/ComponentSmall.png`,
                    data: iconCompsmallBytes
                },
                {
                    name: `${pkgFolder}/Icons/labelicon.png`,
                    data: iconLabelBytes
                }
            ];

            // Only package layout diagram image if authentic image bytes exist
            if (imgFilename && layoutImgBytes) {
                files.push({
                    name: `${pkgFolder}/Images/${imgFilename}`,
                    data: layoutImgBytes
                });
            }

            files.push(
                {
                    name: `${pkgFolder}/Accessories_BOM.csv`,
                    data: accCsv
                },
                {
                    name: `${pkgFolder}/Pin_Schedule.txt`,
                    data: pinSummary
                }
            );

            // 10. Generate ZIP Blob
            return createZip(files);
        },

        /**
         * Builds and triggers browser download of a .SkyCadPackage
         */
        downloadConnectorPackage: async function(connectorData) {
            try {
                if (!connectorData.partNumber || !connectorData.partNumber.startsWith('D38999/')) {
                    alert('SkyCAD package export is currently supported for MIL-DTL-38999 Series III connectors only.');
                    return;
                }
                const blob = await this.generatePackageBlob(connectorData);
                const safePN = connectorData.safePN || this.toSafePN(connectorData.partNumber);
                const fileName = `${safePN}.SkyCadPackage`;

                const url = URL.createObjectURL(blob);
                const a = document.createElement('a');
                a.href = url;
                a.download = fileName;
                document.body.appendChild(a);
                a.click();
                setTimeout(() => {
                    document.body.removeChild(a);
                    URL.revokeObjectURL(url);
                }, 1500);

                return true;
            } catch (err) {
                console.error('SkyCAD package generation error:', err);
                alert(`Failed to export SkyCAD package: ${err.message}`);
                return false;
            }
        }
    };

    // Expose to window
    window.SkyCadExporter = SkyCadExporter;

})(typeof window !== 'undefined' ? window : this);
